import { existsSync, readFileSync, readdirSync } from "node:fs";
import { basename, join, resolve } from "node:path";

// Attributes the generated bytes of built client chunks to npm packages and
// workspace folders by decoding each chunk's source map. Usage:
//   node scripts/benchmarks/dashboard-bundle.mjs <assets dir> [urls.json]
// urls.json is a JSON array of chunk URLs or file names (for example the JS a
// page loaded); without it every chunk in the directory is counted.
const assets = resolve(
  process.argv[2] ?? "apps/dashboard/.output/public/assets"
);
const files = process.argv[3]
  ? [
      ...new Set(
        JSON.parse(readFileSync(process.argv[3], "utf8")).map((url) =>
          basename(new URL(url, "http://x").pathname)
        )
      ),
    ]
  : readdirSync(assets).filter((name) => name.endsWith(".js"));

const BASE64 =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const decodeSegment = (segment) => {
  const values = [];
  let value = 0;
  let shift = 0;
  for (const char of segment) {
    const digit = BASE64.indexOf(char);
    value += (digit & 31) << shift;
    if (digit & 32) {
      shift += 5;
    } else {
      values.push(value & 1 ? -(value >>> 1) : value >>> 1);
      value = 0;
      shift = 0;
    }
  }
  return values;
};

const owner = (source) => {
  const modules = source.split("node_modules/");
  if (modules.length > 1) {
    const parts = modules.at(-1).split("/");
    return parts[0].startsWith("@") ? parts.slice(0, 2).join("/") : parts[0];
  }
  const match = source.match(/(apps|packages)\/[^/]+(\/src\/[^/]+)?/);
  if (match) {
    return match[0];
  }
  const local = source.match(/(?:^|\/)src\/[^/]+/);
  return local ? `dashboard/${local[0].replace(/^\//, "")}` : "(other)";
};

const totals = new Map();
let total = 0;
let unmapped = 0;
for (const file of files) {
  const path = join(assets, file);
  const bytes = readFileSync(path);
  total += bytes.length;
  if (!existsSync(`${path}.map`)) {
    unmapped += bytes.length;
    continue;
  }
  const code = bytes.toString("utf8").split("\n");
  const map = JSON.parse(readFileSync(`${path}.map`, "utf8"));
  let sourceIndex = 0;
  let attributed = 0;
  const add = (key, text) => {
    const size = Buffer.byteLength(text);
    attributed += size;
    totals.set(key, (totals.get(key) ?? 0) + size);
  };
  for (const [lineIndex, line] of map.mappings.split(";").entries()) {
    const text = code[lineIndex] ?? "";
    const segments = [];
    let column = 0;
    for (const segment of line.split(",").filter(Boolean)) {
      const [columnDelta, sourceDelta] = decodeSegment(segment);
      column += columnDelta;
      if (sourceDelta !== undefined) {
        sourceIndex += sourceDelta;
      }
      segments.push({
        column,
        source: sourceDelta === undefined ? -1 : sourceIndex,
      });
    }
    add("(generated)", text.slice(0, segments[0]?.column ?? text.length));
    for (const [index, { column: start, source }] of segments.entries()) {
      const end = segments[index + 1]?.column ?? text.length;
      add(
        source < 0 ? "(generated)" : owner(map.sources[source]),
        text.slice(start, end)
      );
    }
  }
  totals.set(
    "(generated)",
    (totals.get("(generated)") ?? 0) + bytes.length - attributed
  );
}

const rows = [...totals]
  .toSorted((a, b) => b[1] - a[1])
  .slice(0, Number(process.env.TOP ?? 40))
  .map(([name, bytes]) => ({
    name,
    kB: Math.round(bytes / 1000),
    share: `${((100 * bytes) / total).toFixed(1)}%`,
  }));
console.log(
  JSON.stringify({
    files: files.length,
    totalKB: Math.round(total / 1000),
    unmappedKB: Math.round(unmapped / 1000),
  })
);
console.table(rows);
